  "eventSales.title": "Продаж на сайті",
  "help.salesSwitch": "«Скоро в продажу»: афіша залишається, а кнопка «Квитки» неактивна. «Розпродано»: афіша автоматично отримує стрічку SOLD OUT. Кнопка неактивна, а картка не має посилання. Продані квитки не змінюються. Перемикач діє одночасно на кожному сайті, який продає цей сеанс.",
  "help.eventsStatus": "Статус окремий для кожної дати. Він також показує, чи є квитки в продажу.",
  "help.eventSales": "Ми рахуємо за замовленнями. Квитки з поверненням коштів віднімаємо.",
  "help.eventDetails": "Покупці бачать назву й опис на сторінці заходу та в листах із квитками. Афішу та текст листів ми зберігаємо окремо. У кожного своя кнопка.",
  "help.materials": "Афіша береться із заходу. Фото, відео та посилання «Інші продавці» однакові для кожної мови сторінки.",
  "help.partners": "Посилання однакові для кожної мови.",
  "help.report": "Фотозвіт, відео й текст ми публікуємо в архіві заходу. Їх можна редагувати після дати заходу.",
  "help.invitations": "Безкоштовний квиток проходить звичайну покупку з ціною нуль. Одержувач отримує лише лист із квитком. Службових листів про замовлення він не отримує. Лист надсилається мовою, яку ви вибрали вгорі сторінки.",
  "help.orderLetters": "Статус надходить від поштової служби. Ми визначаємо відкритий лист за зображенням, якого покупець не бачить. Це не завжди точно. Поштові програми можуть блокувати зображення або відкривати його автоматично.",
  "help.letterText": "Він іде покупцю разом із квитками в PDF, мовою замовлення. Стандартний лист є кожною мовою. Свій текст ви пишете для одного заходу.",
  "help.refundQueue": "Цей список показує, що має зробити людина. Лист із квитками не дійшов. Оплачене замовлення скасоване, а його квитки діють. Повернення коштів поза Arena потребує ручної перевірки. Квиток чекає на скасування. Покупець не отримав гроші назад.",
  "salesState.segment.open": "Продаж відкрито",
  "salesState.segment.soon": "Скоро в продажу",
  "salesState.segment.sold_out": "Розпродано",
  "salesState.autoShown": "Платформа показує «{state}». Вільних місць не залишилось або продаж категорій не почався. Виберіть сегмент, щоб задати статус вручну.",
  "salesState.openNoop": "Статус вручну не задано, тож відкривати нічого. Платформа показує «{state}», доки не з'являться вільні місця й не почнуться дати продажу.",
  "wizard.create.hint.venueCreate": "Ваша роль не дозволяє додавати майданчики. Виберіть майданчик зі списку або попросіть власника додати новий майданчик.",
  "wizard.venue.noCreate": "Ваша роль не дозволяє додавати майданчики. Виберіть майданчик зі списку. Якщо майданчика немає в списку, попросіть власника додати його.",
  "wizard.venue.noAccess": "Ваша роль не дозволяє бачити та додавати майданчики, тож додати захід тут не можна. Зверніться до власника організації.",
  "wizard.venue.noneNoCreate": "В організації немає майданчиків, а ваша роль не дозволяє додавати майданчик. Попросіть власника додати майданчик.",
  "wizard.venue.newNote": "Ми додамо майданчик до організації, коли ви натиснете «Додати захід». Після цього його можна вибирати для інших заходів.",
  "wizard.f.address": "Адреса",
  "wizard.f.addressHint": "Вулиця й номер. Покупці бачать її на квитку. Це поле необов'язкове.",
  "wizard.err.addressLong": "Адреса задовга. Скоротіть її до 200 символів.",
  "wizard.create.partial": "У чернетці заходу збережено дат: {saved} із {total}. Дату {n} не збережено. Натисніть кнопку ще раз. Збережені дати вдруге не додаються.",
  "wizard.create.unknown.venue": "Ми не знаємо, чи додано новий майданчик.",
  "wizard.create.deniedVenue": "Ваша роль не дозволяє додавати майданчики, тож ми не додали захід. Ваша форма залишається як є. Виберіть майданчик зі списку або попросіть власника додати новий майданчик.",
  "wizard.create.deniedPartial": "Ваша роль не дозволяє додавати до цього заходу ще дати. Ваша форма залишається як є. Зверніться до власника організації.",
  "wizard.create.rejected.venue": "Платформа не додала новий майданчик, тож ми не додали захід. Ваша форма залишається як є.",
